// export default NavBar;

import React, { useEffect, useRef, useState } from "react";
import {
  Bell,
  BookOpen,
  Check,
  CheckCheck,
  CircleUser,
  FileText,
  GraduationCap,
  MessageCircle,
  Minimize,
  Scan,
} from "lucide-react";
import { Badge } from "@mui/material";
import { jwtDecode } from "jwt-decode";
import { useNavigate, useLocation } from "react-router-dom";
import MaterialRipple from "material-ripple-effects";
import { supabase } from "../supabaseClient";
import Profile from "../pages/Profile";
import { logoutCurrentSession } from '../API/sessionAPI';
import GetVolumeData from '../API/getVolumeData';
import { GetQueriesAPI } from '../API/GetQueriesAPI';
import clearLocalSession from '../Auth/clearLocalSession';

function NavBar() {
  const navigate = useNavigate();
  const location = useLocation();
  const ripple = new MaterialRipple();
  const dropdownRefs = useRef({});
  const currentPath = location.pathname;

  // ── Auth ──────────────────────────────────────────────────────────────────
  const tokenRes = jwtDecode(localStorage.getItem("user_token"));
  const isAdmin = [99, 101, 102].includes(Number(tokenRes.role));

  // ── UI state ──────────────────────────────────────────────────────────────
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [openDropdownIndex, setOpenDropdownIndex] = useState(null);

  // ── Notification state ────────────────────────────────────────────────────
  const [count, setCount] = useState(0);
  const [notify, setNotify] = useState([]);
  const readNotificationsKey = `navbar-read-notifications:${tokenRes?.user_mail ?? "guest"}`;
  const [readNotificationIds, setReadNotificationIds] = useState(() => {
    try {
      return new Set(JSON.parse(localStorage.getItem(readNotificationsKey) || "[]"));
    } catch {
      return new Set();
    }
  });

  const getNotificationId = (notification) => {
    const id =
      notification.query_id ??
      notification.course_id ??
      notification.target_learning_id ??
      notification.volume_id ??
      notification.created_at ??
      notification.added_by;

    return `${notification.type}:${id}`;
  };

  const notificationIsRead = (notification, readIds = readNotificationIds) =>
    Boolean(notification.is_read) || readIds.has(getNotificationId(notification));

  useEffect(() => {
    localStorage.setItem(
      readNotificationsKey,
      JSON.stringify([...readNotificationIds])
    );
  }, [readNotificationIds, readNotificationsKey]);

  // ── Page title helper ─────────────────────────────────────────────────────
  const getPageTitle = (loc) => {
    const path = (loc?.pathname || window.location.pathname).toLowerCase();
    const search = new URLSearchParams(loc?.search || window.location.search);
    
    if (path === "/batch" && search.get("tab") === "targeted") {
      return "Targeted Learning";
    }

    if (path === "/dashboard") return "Dashboard";
    if (path === "/my-learning") return "My Learning";
    if (path === "/my-progress") return "My Progress";
    if (path === "/schedules") return "Schedules";
    if (path === "/queries") return "Queries";
    if (path === "/batch" || path.startsWith("/batch/")) return "Batch";
    if (path === "/trainees") return "Trainees";
    if (path.startsWith("/trainee/")) return "Trainee Details";
    if (path === "/instructors") return "Instructors";
    if (path.startsWith("/instructor/")) return "Instructor Details";
    if (path === "/certificate" || path === "/course" || path.startsWith("/course/") || path.startsWith("/chapters/") || path.startsWith("/module/") || path.startsWith("/resource/") || path.startsWith("/cert-course/") || path.startsWith("/cert_course/")) return "Certification";
    if (path === "/curriculum") return "Curriculum";
    if (path === "/volume-management") return "Volume Management";
    if (path === "/cluster") return "Cluster";
    if (path === "/request-raised" || path === "/all-requests") return "Requests";
    if (path === "/course-mapping") return "Course Mapping";
    if (path === "/reatt-data") return "Reattempts";
    if (path === "/academics") return "Academics";
    if (path === "/vrspace" || path === "/video" || path === "/publish") return "Streams";
    if (path === "/reports") return "Reports";
    if (path === "/settings") return "Settings";
    if (path === "/sessions") return "Sessions";
    if (path === "/profile") return "Profile";
    if (path === "/custom-course") return "SVT Course";
    if (path === "/course-access") return "Assigned Courses";

    const cleanPath = path.replace(/^\//, '').split('/')[0];
    if (cleanPath) {
      return cleanPath.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
    }
    return "Dashboard";
  };

  const pageTitle = getPageTitle(location);

  const roleLabel = {
    99: "Welcome Super Admin",
    101: "Welcome Admin",
    102: "Welcome Instructor",
  }[tokenRes.role];

  // ── Fullscreen ────────────────────────────────────────────────────────────
  useEffect(() => {
    const handleChange = () => {
      const fs = !!document.fullscreenElement;
      setIsFullscreen(fs);
      localStorage.setItem("isFullscreen", fs);
    };
    document.addEventListener("fullscreenchange", handleChange);
    return () => document.removeEventListener("fullscreenchange", handleChange);
  }, []);

  const toggleFullscreen = async () => {
    if (!document.fullscreenElement) {
      await document.documentElement.requestFullscreen();
    } else {
      await document.exitFullscreen();
    }
  };

  // ── Close dropdown on outside click ──────────────────────────────────────
  useEffect(() => {
    const handleClickOutside = (e) => {
      const inside = Object.values(dropdownRefs.current).some(
        (ref) => ref && ref.contains(e.target)
      );
      if (!inside) setOpenDropdownIndex(null);
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const toggleDropdown = (index) => {
    const isOpening = openDropdownIndex !== index;
    setOpenDropdownIndex(isOpening ? index : null);
    if (index === "notifications" && isOpening) fetchCount();
  };

  // ── Fetch notifications ───────────────────────────────────────────────────
  const isFetchingCountRef = useRef(false);
  const fetchCount = async () => {
    if (isFetchingCountRef.current) return;
    isFetchingCountRef.current = true;
    try {
      const mail = tokenRes?.user_mail || "";
      const role = Number(tokenRes?.role);
      const token = localStorage.getItem("user_token");
      const emptyResult = { data: [], count: 0 };
      const [courseRes, traineeRes, volumeRes, queryRes] = await Promise.all([
        // Unread course assignments (handled via API)
        Promise.resolve(emptyResult),

        // Targeted learning belongs only to the signed-in trainee.
        role === 103 && mail
          ? supabase
              .from("targeted_learning")
              .select("tar_name, target_learning_id, created_at", { count: "exact" })
              .contains("trainee_id", [mail])
              .then((r) => (r.error ? emptyResult : r))
              .catch(() => emptyResult)
          : Promise.resolve(emptyResult),

        // Institution Admins see pending uploads from instructors in their center.
        role === 101 && tokenRes?.centre_id
          ? GetVolumeData(token)
              .then((response) => {
                const data = (Array.isArray(response?.data) ? response.data : [])
                  .filter((volume) =>
                    volume.status === false &&
                    Number(volume.uploader_role) === 102 &&
                    volume.added_by !== mail
                  );
                return { data, count: data.length };
              })
              .catch(() => emptyResult)
          : Promise.resolve(emptyResult),

        // This API applies the authenticated admin's center scope server-side.
        [99, 101].includes(role)
          ? GetQueriesAPI(token, 1, 20)
              .then((response) => {
                const data = (Array.isArray(response?.result) ? response.result : [])
                  .filter((query) => query.status !== "resolved");
                return { data, count: data.length };
              })
              .catch(() => emptyResult)
          : Promise.resolve(emptyResult),
      ]);

      const allData = [
        ...(courseRes.data?.map((d) => ({ ...d, type: "course" })) || []),
        ...(traineeRes.data?.map((d) => ({ ...d, type: "trainee" })) || []),
        ...(volumeRes.data?.map((d) => ({ ...d, type: "volumes" })) || []),
        ...(queryRes?.data?.map((d) => ({ ...d, type: "query" })) || []),
      ];

      setNotify(allData);
      setCount(
        allData.filter((notification) => !notificationIsRead(notification)).length
      );
    } catch (err) {
      console.error("Error fetching notifications:", err);
    } finally {
      isFetchingCountRef.current = false;
    }
  };

  // ── Mark course notification as read ─────────────────────────────────────
  // ── Mark query notification as read (local only) ──────────────────────────
  // ── Real-time subscriptions ───────────────────────────────────────────────
  useEffect(() => {
    fetchCount();

    const courseChannel = supabase
      .channel("course_availability")
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "course_availability", filter: `user_id=eq.${tokenRes.user_mail}` },
        async (payload) => {
          if (payload.new.user_id === tokenRes.user_mail) {
            setCount((prev) => prev + 1);
            await fetchCount();
          }
        }
      )
      .subscribe();

    // Array-based targeted-learning subscriptions cannot be safely tenant-filtered here.
    const traineeChannel = null;

    const volumeChannel = Number(tokenRes.role) === 101 && tokenRes.centre_id ? supabase
      .channel(`volumes:${tokenRes.centre_id}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "volumes",
          filter: `owner_centre_id=eq.${tokenRes.centre_id}`,
        },
        async (payload) => {
          if (
            Number(payload.new.uploader_role) === 102 &&
            payload.new.added_by !== tokenRes.user_mail &&
            payload.new.status === false
          ) {
            await fetchCount();
          }
        }
      )
      .subscribe() : null;

    return () => {
      supabase.removeChannel(courseChannel);
      if (traineeChannel) supabase.removeChannel(traineeChannel);
      if (volumeChannel) supabase.removeChannel(volumeChannel);
    };
  }, []);

  // ── Logout ────────────────────────────────────────────────────────────────
  const handleLogout = async () => {
    try {
      await logoutCurrentSession();
    } finally {
      clearLocalSession();
      navigate("/");
    }
  };

  // ── Notification message helper ───────────────────────────────────────────
  const getNotificationMessage = (n) => {
    if (n.type === "course") return "A course has been assigned to you";
    if (n.type === "trainee") return "Targeted learning has been initiated";
    if (n.type === "volumes")
      return `${n.user_name ?? n.added_by} uploaded a volume`;
    if (n.type === "query")
      return `New query raised: "${n.subject}" by ${n.user_name ?? n.created_by}`;
    return "New notification";
  };

  const getNotificationRoute = (n) => {
    if (n.type === "volumes") return "/request-raised";
    if (n.type === "query") return "/queries";
    if (n.type === "trainee") return "/batch?tab=targeted";
    return "/dashboard";
  };

  const getNotificationIcon = (type) => {
    if (type === "course") return BookOpen;
    if (type === "trainee") return GraduationCap;
    if (type === "volumes") return FileText;
    return MessageCircle;
  };

  const getNotificationTime = (n) => {
    if (!n.created_at) return "New";

    const elapsedMinutes = Math.max(
      0,
      Math.floor((Date.now() - new Date(n.created_at).getTime()) / 60000)
    );
    if (elapsedMinutes < 1) return "Just now";
    if (elapsedMinutes < 60) return `${elapsedMinutes}m ago`;
    if (elapsedMinutes < 1440) return `${Math.floor(elapsedMinutes / 60)}h ago`;
    if (elapsedMinutes < 10080) return `${Math.floor(elapsedMinutes / 1440)}d ago`;
    return new Intl.DateTimeFormat("en", {
      month: "short",
      day: "numeric",
    }).format(new Date(n.created_at));
  };

  const handleMarkRead = async (notification) => {
    if (notificationIsRead(notification)) return;

    const notificationId = getNotificationId(notification);
    setReadNotificationIds((previous) => new Set([...previous, notificationId]));
    setNotify((previous) =>
      previous.map((item) =>
        getNotificationId(item) === notificationId
          ? { ...item, is_read: true }
          : item
      )
    );
    setCount((previous) => Math.max(previous - 1, 0));

    if (notification.type === "course") {
      const { error } = await supabase
        .from("course_availability")
        .update({ is_read: true })
        .eq("course_id", notification.course_id)
        .eq("user_id", tokenRes.user_mail);
      if (error) console.error("Error marking notification as read:", error);
    }
  };

  const handleMarkAllRead = async () => {
    const unreadNotifications = notify.filter(
      (notification) => !notificationIsRead(notification)
    );
    if (!unreadNotifications.length) return;

    const unreadIds = unreadNotifications.map(getNotificationId);
    setReadNotificationIds(
      (previous) => new Set([...previous, ...unreadIds])
    );
    setNotify((previous) =>
      previous.map((notification) => ({ ...notification, is_read: true }))
    );
    setCount(0);

    const courseIds = unreadNotifications
      .filter((notification) => notification.type === "course")
      .map((notification) => notification.course_id);
    if (courseIds.length) {
      const { error } = await supabase
        .from("course_availability")
        .update({ is_read: true })
        .in("course_id", courseIds)
        .eq("user_id", tokenRes.user_mail);
      if (error) console.error("Error marking all notifications as read:", error);
    }
  };

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <>
      <div className="navbar dm-sans">
        <nav className="border-b border-[#6e9f2e]/60 bg-gradient-to-r from-[#78aa35] via-[#8DC63F] to-[#9dce5b] shadow-[0_8px_22px_-16px_rgba(70,105,28,0.9)]">
          <div className="flex min-h-[50px] flex-wrap items-center justify-between px-2 py-1 sm:px-3">

            {/* Left: page title */}
            <div className="ms-2 flex items-center gap-3 sm:ms-3">
              <div className="hidden h-8 w-8 items-center justify-center rounded-xl bg-white/20 text-white shadow-inner sm:flex"><GraduationCap size={18} /></div>
              <div className="leading-tight">
                <div className="hidden text-[10px] font-bold uppercase tracking-[0.16em] text-white/70 sm:block">ANU Learning Hub</div>
                {pageTitle && <div className="text-sm font-semibold text-white">{pageTitle}</div>}
              </div>
            </div>

            {/* Right: action icons */}
            <div className="flex md:order-2 items-center">

              {/* Role greeting */}
              {roleLabel && (
                <div className="hidden items-center gap-2 rounded-full border border-white/25 bg-white/10 px-3 py-1.5 text-xs font-semibold text-white shadow-inner md:flex">
                  <span className="h-1.5 w-1.5 rounded-full bg-white shadow-[0_0_0_3px_rgba(255,255,255,0.18)]" />{roleLabel}
                </div>
              )}

              {/* Search */}
              {/* <div className="px-3 py-2 ms-1 text-gray-200">
                <button aria-label="Search">
                  <Search size={20} />
                </button>
              </div> */}

              {/* Fullscreen toggle */}
              <div className="ms-1 px-1 py-1 text-white/85">
                <button onClick={toggleFullscreen} aria-label="Toggle fullscreen" className="flex h-8 w-8 items-center justify-center rounded-full transition hover:bg-white/20 focus:outline-none focus:ring-2 focus:ring-white/50">
                  {isFullscreen ? <Minimize size={20} /> : <Scan size={20} />}
                </button>
              </div>

              {/* Notifications */}
              <div
                ref={(el) => (dropdownRefs.current["notifications"] = el)}
                className="relative md:block px-2 py-1.5 ms-1 text-gray-100"
              >
                <button
                  onClick={() => toggleDropdown("notifications")}
                  className={`relative flex h-8 w-8 items-center justify-center rounded-full transition-colors duration-200 hover:bg-white/20 focus:outline-none focus:ring-2 focus:ring-white/60 ${
                    openDropdownIndex === "notifications" ? "bg-white/20" : ""
                  }`}
                  aria-label="Notifications"
                  aria-haspopup="menu"
                  aria-expanded={openDropdownIndex === "notifications"}
                >
                  <Badge badgeContent={count} color="error" max={99}>
                    <Bell size={20} />
                  </Badge>
                </button>

                {openDropdownIndex === "notifications" && (
                  <div
                    className="absolute right-0 z-50 mt-2 w-[calc(100vw-1.5rem)] overflow-hidden rounded-2xl border border-slate-200/80 bg-white text-slate-900 shadow-[0_20px_55px_-15px_rgba(15,23,42,0.35)] sm:w-[420px]"
                    role="menu"
                  >
                    <div className="flex items-center justify-between border-b border-slate-100 bg-gradient-to-r from-lime-50 via-white to-white px-5 py-4">
                      <div>
                        <div className="flex items-center gap-2">
                          <h2 className="text-base font-semibold text-slate-900">
                            Notifications
                          </h2>
                          {count > 0 && (
                            <span className="rounded-full bg-[#8DC63F]/15 px-2 py-0.5 text-xs font-semibold text-[#5f8f20]">
                              {count} new
                            </span>
                          )}
                        </div>
                        <p className="mt-0.5 text-xs text-slate-500">
                          Your latest learning updates
                        </p>
                      </div>

                      {count > 0 && (
                        <button
                          type="button"
                          onClick={handleMarkAllRead}
                          className="flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-semibold text-[#659624] transition-colors hover:bg-[#8DC63F]/10 focus:outline-none focus:ring-2 focus:ring-[#8DC63F]/30"
                        >
                          <CheckCheck size={15} />
                          Mark all read
                        </button>
                      )}
                    </div>

                    {notify.length > 0 ? (
                      <ul className="max-h-[380px] divide-y divide-slate-100 overflow-y-auto overscroll-contain">
                        {notify.map((n, idx) => {
                          const read = notificationIsRead(n);
                          const NotificationIcon = getNotificationIcon(n.type);

                          return (
                            <li
                              key={getNotificationId(n) || idx}
                              className={`relative px-4 py-3.5 transition-colors hover:bg-slate-50/80 ${
                                read ? "bg-white" : "bg-[#8DC63F]/[0.045]"
                              }`}
                            >
                              {!read && (
                                <span className="absolute left-0 top-0 h-full w-1 bg-[#8DC63F]" />
                              )}
                              <div className="flex items-start gap-3">
                                <div
                                  className={`mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${
                                    read
                                      ? "bg-slate-100 text-slate-500"
                                      : "bg-[#8DC63F]/15 text-[#679b22]"
                                  }`}
                                >
                                  <NotificationIcon size={18} />
                                </div>

                                <div className="min-w-0 flex-1">
                                  <div className="flex items-start justify-between gap-3">
                                    <p
                                      className={`text-sm leading-5 ${
                                        read
                                          ? "font-normal text-slate-600"
                                          : "font-medium text-slate-900"
                                      }`}
                                    >
                                      {getNotificationMessage(n)}
                                    </p>
                                    {!read && (
                                      <span
                                        className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-[#8DC63F] ring-4 ring-[#8DC63F]/10"
                                        aria-label="Unread"
                                      />
                                    )}
                                  </div>

                                  <div className="mt-2 flex items-center justify-between gap-3">
                                    <span className="text-xs text-slate-400">
                                      {getNotificationTime(n)}
                                    </span>
                                    <div className="flex items-center gap-1.5">
                                      <button
                                        type="button"
                                        onClick={() => {
                                          setOpenDropdownIndex(null);
                                          navigate(getNotificationRoute(n));
                                        }}
                                        className="rounded-lg px-2.5 py-1.5 text-xs font-semibold text-slate-600 transition-colors hover:bg-slate-100 hover:text-slate-900 focus:outline-none focus:ring-2 focus:ring-slate-200"
                                      >
                                        View
                                      </button>
                                      <button
                                        type="button"
                                        onClick={() => handleMarkRead(n)}
                                        disabled={read}
                                        aria-label={read ? "Notification read" : "Mark as read"}
                                        className={`flex items-center gap-1 rounded-lg px-2.5 py-1.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-[#8DC63F]/30 ${
                                          read
                                            ? "cursor-default text-slate-400"
                                            : "text-[#659624] hover:bg-[#8DC63F]/10"
                                        }`}
                                      >
                                        <Check size={14} />
                                        {read ? "Read" : "Mark as read"}
                                      </button>
                                    </div>
                                  </div>
                                </div>
                              </div>
                            </li>
                          );
                        })}
                      </ul>
                    ) : (
                      <div className="flex flex-col items-center px-6 py-10 text-center">
                        <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-lime-50 text-[#75a92f]">
                          <CheckCheck size={23} />
                        </div>
                        <p className="text-sm font-semibold text-slate-700">
                          You&apos;re all caught up
                        </p>
                        <p className="mt-1 text-xs text-slate-400">
                          New updates will appear here.
                        </p>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* User menu */}
              <div className="ms-1 relative">
                <button
                  onClick={() => toggleDropdown("user-options")}
                  className="rounded-full p-2 text-white/90 transition hover:bg-white/20 focus:outline-none focus:ring-2 focus:ring-white/50"
                  onMouseDown={(e) => ripple.create(e, "dark", "circle")}
                  aria-label="User menu"
                >
                  <CircleUser size={20} />
                </button>

                {openDropdownIndex === "user-options" && (
                  <div
                    ref={(el) => (dropdownRefs.current["user-options"] = el)}
                    className="absolute right-0 z-50 mt-2 w-36 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-[0_16px_35px_-12px_rgba(15,23,42,0.3)]"
                  >
                    <button
                      className="block w-full text-left px-4 py-2 hover:bg-gray-50 text-sm"
                      onClick={() => {
                        setOpenDropdownIndex(null);
                        setIsProfileModalOpen(true);
                      }}
                    >
                      Profile
                    </button>
                    <button
                      className="block w-full px-4 py-2.5 text-left text-sm text-slate-700 hover:bg-slate-50"
                      onClick={() => {
                        setOpenDropdownIndex(null);
                        navigate('/sessions');
                      }}
                    >
                      Sessions
                    </button>
                    {/* <button
                      className="block w-full px-4 py-2.5 text-left text-sm text-slate-700 hover:bg-slate-50"
                      onClick={() => navigate("/settings")}
                    >
                      Settings
                    </button> */}
                    <button
                      className="block w-full px-4 py-2.5 text-left text-sm text-slate-700 hover:bg-slate-50"
                      onClick={handleLogout}
                    >
                      Logout
                    </button>
                  </div>
                )}
              </div>

              {/* Mobile hamburger */}
              <button
                type="button"
                className="inline-flex h-10 w-10 items-center justify-center rounded-full p-2 text-sm text-white/90 hover:bg-white/20 focus:outline-none focus:ring-2 focus:ring-white/30 md:hidden"
                aria-label="Open menu"
              >
                <svg
                  className="w-5 h-5"
                  aria-hidden="true"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 17 14"
                >
                  <path
                    stroke="currentColor"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M1 1h15M1 7h15M1 13h15"
                  />
                </svg>
              </button>
            </div>
          </div>
        </nav>
      </div>

      <Profile
        isOpen={isProfileModalOpen}
        onClose={() => setIsProfileModalOpen(false)}
      />
    </>
  );
}

export default NavBar;
